import {countedOptions} from './actuator-analysis.js?v=0.2.2-cm20261103-r2';
import {csvInLanguage,getLanguage} from './i18n.js?v=0.2.2-cm20261103-r2';
import './site-shell.js?v=0.2.2-cm20261103-r2';
import {metricDefinitions as defs,metricValue,formatMetric,filterHands,sortHands,csvForHands,isChina,tactileLabels} from './hand-logic.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(p,k)=>formatMetric(p.metrics?.[k]);
function url(raw,page){try{const u=new URL(raw,location.href);if(!['http:','https:'].includes(u.protocol))return '#';if(page&&/\.pdf$/i.test(u.pathname))u.hash='page='+page;return u.href;}catch{return '#';}}
const defaults=()=>({origin:'all',status:'all',category:'all',brands:new Set(),query:'',dofKind:'activeDof',dofMin:null,dofMax:null,fingers:'all',massMax:null,tactile:'all',drive:'all',sort:'featured'});
let state={...defaults(),view:'cards'},data,products=[],results=[],byId=new Map(),compareIds=[],detailId=null,detailTab='spec',toastTimer;
try{state.view=localStorage.getItem('hand-view')==='list'?'list':'cards';}catch{}
const selectMap={originFilter:'origin',statusFilter:'status',categoryFilter:'category',dofKind:'dofKind',fingersFilter:'fingers',tactileFilter:'tactile',driveFilter:'drive',sortSelect:'sort'};
function picture(p){return p.image?.path?`<img src="${esc(p.image.path)}" alt="${esc(p.brand+' '+p.model)}官方或科研图" loading="lazy" decoding="async">`:'<div class="image-pending"><strong>HAND</strong><span>原图待补</span></div>';}
function metric(p,k,label){return `<div><span class="metric-label">${esc(label||defs[k][0])}</span><span class="metric-value ${metricValue(p,k)===null?'missing':''}">${esc(fmt(p,k))}${metricValue(p,k)!==null?'<small>'+esc(defs[k][1])+'</small>':''}</span></div>`;}
function badge(p){return `<span class="hand-chip ${p.tactileStatus==='unknown'?'unknown':''}">${esc(tactileLabels[p.tactileStatus||'unknown'])}</span>`;}
function addButton(p,table=false){const on=compareIds.includes(p.id);return `<button type="button" class="compare-add ${table?'table-compare':''} ${on?'selected':''}" data-compare="${esc(p.id)}" aria-label="${on?'移除':'加入'}${esc(p.model)}参数对比" aria-pressed="${on}">${on?'✓':'+'}</button>`;}
function card(p){return `<article class="robot-card hand-card">${addButton(p)}<button type="button" class="card-open" data-open="${esc(p.id)}" aria-label="查看 ${esc(p.model)} 详情"><div class="card-media"><span class="type-tag">${esc(p.category)}</span>${picture(p)}</div><div class="card-content"><p class="card-brand">${esc(p.brand)} · ${esc(p.origin)}</p><div class="card-title-line"><h3>${esc(p.model)}</h3></div><p class="card-subtitle">${esc(p.position)}</p><div class="card-metrics">${metric(p,'activeDof','主动自由度')}${metric(p,'fingers')}${metric(p,'massKg','记录质量')}${metric(p,'mechanicalDof','机械自由度')}</div><div class="card-bottom">${badge(p)}<span class="hand-source-count">${esc(p.status)}</span><span class="card-detail-link">详情 →</span></div></div></button></article>`;}
function table(ps){return `<div class="robot-list-wrap"><table class="robot-table hand-table"><thead><tr><th>品牌 / 型号</th><th>地区 / 属性</th><th class="num">手指</th><th class="num">主动 DOF</th><th class="num">机械 DOF</th><th class="num">标称 DOF*</th><th class="num">质量 kg</th><th>触觉</th><th>对比</th></tr></thead><tbody>${ps.map(p=>`<tr><td><button type="button" class="table-robot" data-open="${esc(p.id)}">${picture(p)}<span><strong>${esc(p.model)}</strong><small>${esc(p.brand)}</small></span></button></td><td>${esc(p.origin)}<small class="layer-small">${esc(p.status)}</small></td>${['fingers','activeDof','mechanicalDof','reportedDof','massKg'].map(k=>`<td class="num">${esc(fmt(p,k))}</td>`).join('')}<td>${badge(p)}</td><td>${addButton(p,true)}</td></tr>`).join('')}</tbody></table></div>`;}
function renderFilters(){const names=countedOptions(products,'brand').map(x=>x.value);$('#brandFilters').innerHTML=names.map(name=>`<label class="check-row"><input type="checkbox" name="brand" value="${esc(name)}"><span>${esc(name)}</span><span class="brand-count">${products.filter(p=>p.brand===name).length}</span></label>`).join('');$('#driveFilter').innerHTML='<option value="all">全部驱动</option>'+[...new Set(products.map(p=>p.driveGroup))].map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}
function syncFilters(){for(const [id,k]of Object.entries(selectMap))$('#'+id).value=state[k];for(const k of ['dofMin','dofMax','massMax'])$('#'+k).value=state[k]??'';$('#searchInput').value=state.query;$$('input[name=brand]').forEach(el=>el.checked=state.brands.has(el.value));}
function chips(){const entries=[...state.brands].map(b=>['brand:'+b,b]);for(const [id,k]of Object.entries(selectMap))if(!['dofKind','sort'].includes(k)&&state[k]!=='all')entries.push([k,$('#'+id).selectedOptions[0]?.getAttribute('data-label-zh')||state[k]]);if(state.query)entries.push(['query','搜索：'+state.query]);if(state.dofMin!==null||state.dofMax!==null)entries.push(['dof',defs[state.dofKind][0]+` ${state.dofMin??'不限'}–${state.dofMax??'不限'}`]);if(state.massMax!==null)entries.push(['massMax','质量 ≤ '+state.massMax+' kg']);$('#activeFilters').hidden=!entries.length;$('#activeFilters').innerHTML=entries.map(([key,label])=>`<button class="filter-chip" data-clear="${esc(key)}">${esc(label)} <span>×</span></button>`).join('');}
function render(){results=sortHands(filterHands(products,state),state.sort);$('#resultCount').textContent=results.length+' / '+products.length;$('#resultsContent').className=state.view==='cards'?'robot-grid':'robot-list';$('#resultsContent').innerHTML=results.length?(state.view==='cards'?results.map(card).join(''):table(results)):'<div class="empty-state"><h3>没有符合条件的灵巧手</h3><p>试试放宽筛选。缺失参数不会按零参与筛选。</p><button class="button button-outline" data-reset>重置筛选</button></div>';$$('[data-view]').forEach(b=>{const active=b.dataset.view===state.view;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});chips();}
function reset(){state={...defaults(),view:state.view};syncFilters();render();}
function removeChip(k){if(k.startsWith('brand:'))state.brands.delete(k.slice(6));else if(k==='dof'){state.dofMin=null;state.dofMax=null;}else state[k]=defaults()[k];syncFilters();render();}
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function showDialog(id){if(!$('#'+id).open)$('#'+id).showModal();document.body.classList.add('dialog-open');}
function closeDialog(id){$('#'+id).close();if(id==='detailDialog'){detailId=null;if(location.hash.startsWith('#hand/'))history.replaceState(null,'',location.pathname+location.search);}if(!$$('dialog').some(d=>d.open))document.body.classList.remove('dialog-open');}
function sourceLink(id,page){const s=data.sources[id];return s?`<a href="${esc(url(s.url,page))}" target="_blank" rel="noopener noreferrer">${esc(s.title)}${page?' · P.'+esc(page):''} ↗</a>`:esc(id);}
function sourcesFor(p){return [...new Set([...(p.sourceIds||[]),...Object.values(p.metrics).map(m=>m.source)])];}
function specBody(p){return `<div class="spec-grid">${Object.entries(defs).map(([k,[label,unit]])=>{const m=p.metrics[k];return `<div class="spec-row"><span>${esc(label)}</span><strong class="${m?'':'missing'}">${esc(fmt(p,k))}${m?' '+esc(unit):''}</strong><small>${m?esc(m.condition||'条件待核')+' · '+sourceLink(m.source,m.page):'未披露 / 待核实，不等于 0'}</small></div>`;}).join('')}</div><div class="detail-note"><strong>使用边界</strong>${esc(p.notes||'请以指定版本的官方资料与测试条件为准。')}</div>`;}
function structureBody(p){return `<div class="hand-structure">${[['驱动与传动',p.drive+'；'+p.transmission],['触觉与感知',p.tactile],['通讯接口',(p.protocol||[]).join(' / ')||'未披露'],['获取方式',p.availability]].map(([a,b])=>`<div><h4>${esc(a)}</h4>${esc(b)}</div>`).join('')}</div><p class="hand-note">开源状态：${esc(p.openSource?.status||'待核实')}${p.openSource?.url?` · <a href="${esc(url(p.openSource.url))}" target="_blank" rel="noopener noreferrer">项目 / 仓库 ↗</a>`:''}</p><h3 class="detail-section-title">科研与整机关联</h3>${p.research?.length?p.research.map(r=>`<div class="source-card"><h4>${esc(r.name)}</h4><p>${esc(r.note)}</p><a href="${esc(url(r.url))}" target="_blank" rel="noopener noreferrer">查看项目 / 论文 ↗</a></div>`).join(''):'<p class="detail-empty">本版本尚未补充独立的整机采用记录。</p>'}`;}
function evidenceBody(p){return sourcesFor(p).map(id=>{const s=data.sources[id];return s?`<div class="source-card"><h4>${esc(s.title)}</h4><p>${esc(s.kind)} · ${esc(s.version||data.asof)} · ${esc(s.locator||'产品 / 研究正文')}</p><a href="${esc(url(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.url)}</a></div>`:'';}).join('')+`<p class="hand-note">型号发现参考 All Hands Up；数值以上列一手资料为准。图片出处：${esc(p.image?.credit||'待补')}，${esc(p.image?.caption||'')}。</p>`;}
function renderDetail(){const p=byId.get(detailId);if(!p)return;$('#detailContent').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">${esc(p.brand)} / ${esc(p.origin)}</p><h2>${esc(p.model)}</h2></div><button type="button" class="icon-button" data-close="detailDialog" aria-label="关闭灵巧手详情">×</button></div><div class="detail-main"><div><div class="detail-hero-media">${picture(p)}</div><p class="photo-caption">${esc(p.image?.caption||'官方 / 科研原图')}${p.image?.pageUrl?` · <a href="${esc(url(p.image.pageUrl))}" target="_blank" rel="noopener noreferrer">${esc(p.image.credit||'图片来源')} ↗</a>`:''}</p></div><div><div class="detail-meta"><code>${esc(p.id)}</code><span>${esc(p.status)}</span></div><p class="detail-position">${esc(p.position)}</p><div class="detail-classifications"><span>${esc(p.category)}</span><span>${esc(p.drive)}</span>${badge(p)}</div><div class="detail-top-metrics">${metric(p,'activeDof','主动自由度')}${metric(p,'mechanicalDof','机械自由度')}${metric(p,'massKg','记录质量')}</div><p class="hand-note">自由度是否包含腕部、质量是否包含前臂或驱动箱，请核对下方条件。标称 DOF 未明确主动定义时单独列示。</p></div></div><div class="detail-tabs" role="tablist" aria-label="详情栏目">${[['spec','规格与条件'],['structure','驱动与科研'],['evidence','证据与来源']].map(([k,label])=>`<button type="button" id="tab-${k}" role="tab" aria-controls="detailPanel" aria-selected="${k===detailTab}" tabindex="${k===detailTab?0:-1}" data-tab="${k}" class="${k===detailTab?'active':''}">${label}</button>`).join('')}</div><div class="detail-body" id="detailPanel" role="tabpanel" aria-labelledby="tab-${detailTab}">${detailTab==='spec'?specBody(p):detailTab==='structure'?structureBody(p):evidenceBody(p)}</div><div class="detail-actions"><button type="button" class="button button-outline" id="copyLink">复制型号链接</button><button type="button" class="button button-primary" data-compare="${esc(p.id)}">${compareIds.includes(p.id)?'✓ 已加入对比 · 点击移除':'＋ 加入参数对比'}</button></div>`;}
function openDetail(id){if(!byId.has(id))return;detailId=id;detailTab='spec';renderDetail();if(location.hash!=='#hand/'+encodeURIComponent(id))history.replaceState(null,'','#hand/'+encodeURIComponent(id));showDialog('detailDialog');$('#detailDialog').scrollTop=0;}
function renderTray(){$('#compareTray').hidden=!compareIds.length;$('#compareCount').textContent='已选 '+compareIds.length+' / 4';$('#compareNames').textContent=compareIds.map(id=>byId.get(id).model).join(' · ');$('#compareButton').disabled=compareIds.length<2;}
function toggleCompare(id){if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);else{if(compareIds.length>=4)return toast('一次最多对比 4 个型号');compareIds.push(id);}render();renderTray();if(detailId){const top=$('#detailDialog').scrollTop;renderDetail();$('#detailDialog').scrollTop=top;}}
function compare(){if(compareIds.length<2)return;const ps=compareIds.map(id=>byId.get(id));$('#compareContent').innerHTML=`<div class="comparison-note">主动自由度、机械自由度、标称 DOF 与电机数分列。数值下方保留条件；腕部与外置驱动箱范围不同的记录不宜直接排名。</div><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>参数 / 条件</th>${ps.map(p=>`<th>${picture(p)}<h3>${esc(p.model)}</h3><small>${esc(p.brand)}</small></th>`).join('')}</tr></thead><tbody>${Object.entries(defs).map(([k,[label,unit]])=>`<tr><td>${esc(label)} (${esc(unit)})</td>${ps.map(p=>`<td>${esc(fmt(p,k))}${p.metrics[k]?.condition?'<small>'+esc(p.metrics[k].condition)+'</small>':''}</td>`).join('')}</tr>`).join('')}${[['驱动','drive'],['传动','transmission'],['触觉','tactile'],['使用边界','notes']].map(([label,k])=>`<tr><td>${label}</td>${ps.map(p=>`<td class="text-compare">${esc(p[k]||'—')}</td>`).join('')}</tr>`).join('')}<tr><td>原始资料</td>${ps.map(p=>`<td>${sourcesFor(p).map(id=>sourceLink(id)).join('<br>')}</td>`).join('')}</tr></tbody></table></div>`;showDialog('compareDialog');}
function exportResults(){const blob=new Blob([csvInLanguage(csvForHands(results,data.sources))],{type:'text/csv;charset=utf-8'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=getLanguage()==='en'?`RobotBodyAtlas_DexterousHands_${results.length}.csv`:`机器人本体图鉴_灵巧手_${results.length}条.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('已导出 '+results.length+' 条记录，包含参数条件与来源');}
function filters(open){$('#filterPanel').classList.toggle('open',open);$('#filterShade').hidden=!open;$('#openFilters').setAttribute('aria-expanded',String(open));(open?$('#closeFilters'):$('#openFilters')).focus();}
document.addEventListener('click',async e=>{const a=e.target.closest('[data-open]');if(a)return openDetail(a.dataset.open);const c=e.target.closest('[data-compare]');if(c)return toggleCompare(c.dataset.compare);const close=e.target.closest('[data-close]');if(close)return closeDialog(close.dataset.close);const v=e.target.closest('[data-view]');if(v){state.view=v.dataset.view;try{localStorage.setItem('hand-view',state.view)}catch{}return render();}const chip=e.target.closest('[data-clear]');if(chip)return removeChip(chip.dataset.clear);if(e.target.closest('[data-reset]'))return reset();const t=e.target.closest('[data-tab]');if(t){const top=$('#detailDialog').scrollTop;detailTab=t.dataset.tab;renderDetail();$('#detailDialog').scrollTop=top;$('#tab-'+detailTab).focus();return;}if(e.target.closest('#copyLink'))try{await navigator.clipboard.writeText(location.href);toast('已复制型号链接');}catch{toast('请复制浏览器地址中的型号链接');}});
document.addEventListener('change',e=>{const t=e.target;if(selectMap[t.id]){state[selectMap[t.id]]=t.value;render();}if(t.name==='brand'){t.checked?state.brands.add(t.value):state.brands.delete(t.value);render();}});
$('#searchInput').addEventListener('input',e=>{state.query=e.target.value;render();});for(const k of ['dofMin','dofMax','massMax'])$('#'+k).addEventListener('input',e=>{state[k]=Number.isFinite(e.target.valueAsNumber)?e.target.valueAsNumber:null;render();});
$('#resetButton').onclick=reset;$('#exportButton').onclick=()=>data&&exportResults();$('#openFilters').onclick=()=>filters(true);$('#closeFilters').onclick=()=>filters(false);$('#filterShade').onclick=()=>filters(false);$('#compareButton').onclick=compare;$('#clearCompare').onclick=()=>{compareIds=[];render();renderTray();};for(const id of ['methodButton','dataButton'])$('#'+id).onclick=()=>showDialog('methodDialog');
$$('dialog').forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d.id);});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d.id);});});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$$('dialog').some(d=>d.open)){e.preventDefault();$('#searchInput').focus();}if(e.key==='Escape'&&$('#filterPanel').classList.contains('open'))filters(false);if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const names=['spec','structure','evidence'];detailTab=names[(names.indexOf(detailTab)+(e.key==='ArrowRight'?1:2))%3];renderDetail();$('#tab-'+detailTab).focus();}});
function openHash(){const m=location.hash.match(/^#hand\/(.+)$/);if(m){try{openDetail(decodeURIComponent(m[1]));}catch{}}else if($('#detailDialog').open)closeDialog('detailDialog');}window.addEventListener('hashchange',openHash);
try{const r=await fetch('data/hands.json');if(!r.ok)throw Error('HTTP '+r.status);data=await r.json();products=data.products;byId=new Map(products.map(p=>[p.id,p]));$('#handTotal').textContent=products.length;$('#handBrands').textContent=new Set(products.map(p=>p.brand)).size;$('#chinaTotal').textContent=products.filter(isChina).length;renderFilters();render();openHash();}catch(e){console.error(e);$('#resultsContent').innerHTML='<div class="empty-state"><h3>资料暂未载入</h3><p>请刷新页面重试。</p><a href="hands.html" class="button button-outline">重新载入</a></div>';}
